        $startcol3 = $startcol2 + FrecConsultaClientePeer::NUM_HYDRATE_COLUMNS;

        ClienteEstadoPeer::addSelectColumns($criteria);
        $startcol4 = $startcol3 + ClienteEstadoPeer::NUM_HYDRATE_COLUMNS;

        SoporteClientePeer::addSelectColumns($criteria);
        $startcol5 = $startcol4 + SoporteClientePeer::NUM_HYDRATE_COLUMNS;

        $criteria->addJoin(ClientePeer::FRECCONSULTACLIENTE_ID, FrecConsultaClientePeer::FRECCONSULTACLIENTE_ID, $join_behavior);

        $criteria->addJoin(ClientePeer::CLIENTEESTADO_ID, ClienteEstadoPeer::CLIENTEESTADO_ID, $join_behavior);

        $criteria->addJoin(ClientePeer::SOPORTE_CLIENTE_ID, SoporteClientePeer::SOPORTE_CLIENTE_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseClientePeer', $criteria, $con);
        }


        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = ClientePeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = ClientePeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {
                $cls = ClientePeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                ClientePeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined FrecConsultaCliente rows

                $key2 = FrecConsultaClientePeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
                    $obj2 = FrecConsultaClientePeer::getInstanceFromPool($key2);
                    if (!$obj2) {
    
                        $cls = FrecConsultaClientePeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol2);
                    FrecConsultaClientePeer::addInstanceToPool($obj2, $key2);
                } // if $obj2 already loaded

                // Add the $obj1 (Cliente) to the collection in $obj2 (FrecConsultaCliente)
                $obj2->addCliente($obj1);

            } // if joined row is not null

                // Add objects for joined ClienteEstado rows

                $key3 = ClienteEstadoPeer::getPrimaryKeyHashFromRow($row, $startcol3);
                if ($key3 !== null) {
                    $obj3 = ClienteEstadoPeer::getInstanceFromPool($key3);
                    if (!$obj3) {
    
                        $cls = ClienteEstadoPeer::getOMClass();

                    $obj3 = new $cls();
                    $obj3->hydrate($row, $startcol3);
                    ClienteEstadoPeer::addInstanceToPool($obj3, $key3);
                } // if $obj3 already loaded

                // Add the $obj1 (Cliente) to the collection in $obj3 (ClienteEstado)
                $obj3->addCliente($obj1);

            } // if joined row is not null

                // Add objects for joined SoporteCliente rows

                $key4 = SoporteClientePeer::getPrimaryKeyHashFromRow($row, $startcol4);
                if ($key4 !== null) {
                    $obj4 = SoporteClientePeer::getInstanceFromPool($key4);
                    if (!$obj4) {
    
                        $cls = SoporteClientePeer::getOMClass();

                    $obj4 = new $cls();
                    $obj4->hydrate($row, $startcol4);
                    SoporteClientePeer::addInstanceToPool($obj4, $key4);
                } // if $obj4 already loaded

                // Add the $obj1 (Cliente) to the collection in $obj4 (SoporteCliente)
                $obj4->addCliente($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


